import json,subprocess,sys,random
random.seed(31337)
reqs=[]
for _ in range(1500):
    P=random.randint(1,3);R=random.randint(0,4);D=random.randint(0,3)
    inputs=[[[random.randint(-5,5) for _ in range(D)] for _ in range(R)] for _ in range(P)]
    op=random.choice(["replay","audit","export"])
    if op=="replay":
        slots=random.randint(1,4);window=random.randint(1,slots)
        ev=[]
        for _ in range(random.randint(0,15)):
            t=random.choice(["send","retry","deliver","drop","duplicate"])
            if t=="send" and R>0: ev.append(["send",random.randrange(P),random.randrange(R)])
            elif t=="retry": ev.append(["retry",random.randrange(P)])
            else: ev.append([t,random.randint(0,10)])
        reqs.append({"op":op,"inputs":inputs,"slots":slots,"window":window,"events":ev})
    else:
        n=random.randint(1,8)
        states=[]
        for i in range(n):
            delivered=[[ [random.randint(-5,5) for _ in range(D)] for _ in range(random.randint(0,R))] for _ in range(P)]
            states.append({"delivered":delivered,"slots":[]})
        edges=[];seen=set()
        for _ in range(random.randint(0,12)):
            s=random.randrange(n);t=random.randrange(n);a=random.choice(["a","b","c","d"])
            if (s,a,t) in seen:continue
            seen.add((s,a,t));edges.append([s,a,t])
        start=random.randrange(n)
        fair=[];used=set()
        for _ in range(random.randint(0,4)):
            a=random.choice(["a","b","c","d"])
            if a in used:continue
            used.add(a);fair.append({"action":a,"mode":random.choice(["weak","strong"])})
        reqs.append({"op":op,"inputs":inputs,"states":states,"edges":edges,"start":start,"fairness":fair})
data=b'\n'.join(json.dumps(r).encode() for r in reqs)
p=subprocess.run([sys.executable,"-I","/app/submission/main.py"],input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
print("rc",p.returncode,"lines in",len(reqs),"out",len(p.stdout.splitlines()),"err",p.stderr[:300])
# verify each output parses and has correct key set per op
outs=p.stdout.splitlines()
assert len(outs)==len(reqs)
for r,o in zip(reqs,outs):
    d=json.loads(o)
    if "error" in d:
        assert set(d)=={"error"}
    elif r["op"]=="replay":
        assert set(d)=={"hosts","floor","slots","packets","events"}
    elif r["op"]=="audit":
        assert set(d)=={"safe","safety","terminates","liveness"}
    else:
        assert set(d)=={"module","config"}
print("all outputs structurally ok")
PYEOF
